function refreshIds(value){if(value&&typeof value==='object'){const oldIds=new Map();const collect=o=>{if(!o||typeof o!=='object')return;if(o.id){const old=o.id;o.id=uid();oldIds.set(old,o.id);}Object.values(o).forEach(v=>{if(Array.isArray(v))v.forEach(collect);else if(v&&typeof v==='object')collect(v);});};collect(value);const redirect=o=>{if(!o||typeof o!=='object')return;if(o.next&&oldIds.has(o.next))o.next=oldIds.get(o.next);Object.values(o).forEach(v=>{if(Array.isArray(v))v.forEach(redirect);else if(v&&typeof v==='object')redirect(v);});};redirect(value);}}
