async function openCourse(id,force=false){clearTimeout(timer);const cached=await local('get',id);let result;try{result=await read('get',id);}catch(e){if(!cached)throw e;result={data:cached.data,version:cached.version,local:true};}
 course=normalizeCourse(result.data);version=result.version;remote=result.local?!!cached?.remote:true;dirty=!!result.local&&cached?.dirty;serial=0;history=[];future=[];lessonId=course.lessons[0].id;blockId=null;panel='lesson';setStatus(remote?'Saved to website ✓':'Device draft · unsynced',!remote);renderEditor();
 if(cached?.dirty&&!force&&!result.local){show('<h2>Recover your device draft?</h2><p>A draft on this device contains edits that were not saved to the shared course. Your current shared version is already open. You can download the device draft, recover it as a separate course, or continue with the shared version.</p><div class="hero-actions"><button id="recover-copy" class="primary">Recover as new course</button><button id="recover-json">Download device draft</button><button id="keep-shared">Use shared version</button></div>');byId('recover-copy').onclick=()=>{const data=clone(cached.data);refreshIds(data);data.title+=' (recovered)';close();createCourse(data).catch(error);};byId('recover-json').onclick=()=>download(JSON.stringify(cached.data,null,2),'Recovered_lesson_draft.json','application/json');byId('keep-shared').onclick=()=>{backup();close();};}else backup();
}
function blockLibrary(position){let filter='All';show('<h2>Add a block</h2><p>Choose the way learners should experience this idea.</p><input id="block-search" placeholder="Search blocks…" aria-label="Search blocks"><div class="filter-tabs" id="block-filters"></div><div class="block-library" id="block-library"></div>');
 const draw=()=>{const q=byId('block-search').value.toLowerCase();byId('block-filters').innerHTML=['All','Text','Media','Interactive','Assessment','Visual','Structure','Templates'].map(cat=>'<button class="small '+(cat===filter?'active':'')+'" data-filter="'+cat+'">'+cat+'</button>').join('');byId('block-filters').querySelectorAll('button').forEach(btn=>btn.onclick=()=>{filter=btn.dataset.filter;draw();});
  const options=CATALOG.filter(x=>(filter==='All'||x.category===filter)&&[x.label,x.hint].join(' ').toLowerCase().includes(q));byId('block-library').innerHTML=filter==='Templates'?templates.filter(t=>t.description!==THEME_TEMPLATE_MARKER).map(t=>'<button class="block-option" data-template="'+t.id+'"><span>☆</span><div><strong>'+esc(t.title)+'</strong><small>Saved reusable block</small></div></button>').join('')||'<p>No templates yet. Use the ☆ button on a block to save one.</p>':options.map(x=>'<button class="block-option" data-type="'+x.type+'"><span>'+x.icon+'</span><div><strong>'+esc(x.label)+'</strong><small>'+esc(x.hint)+'</small></div></button>').join('');
  byId('block-library').querySelectorAll('[data-type]').forEach(btn=>btn.onclick=()=>add(newBlock(btn.dataset.type)));
  byId('block-library').querySelectorAll('[data-template]').forEach(btn=>btn.onclick=async()=>{try{const result=await read('get',btn.dataset.template);const b=clone(result.data.lessons[0].blocks[0]);refreshIds(b);add(b);}catch(e){error(e);}});
 };const add=b=>{remember(true);selectedLesson().blocks.splice(position,0,b);blockId=b.id;panel='block';panelTab='content';close();changed(true);};byId('block-search').oninput=draw;draw();
}

function manageTemplates(){show('<h2>Your reusable block templates</h2><p>Edit a template through the same content forms, or archive templates you no longer need. Courses already using a template keep their own editable copies.</p>'+templates.filter(t=>t.description!==THEME_TEMPLATE_MARKER).map(t=>'<div class="history-row"><span>'+esc(t.title)+'</span><div><button data-edit-template="'+t.id+'">Edit</button> <button data-remove-template="'+t.id+'" class="danger">Archive</button></div></div>').join('')+(templates.some(t=>t.description!==THEME_TEMPLATE_MARKER)?'':'<div class="notice">Use the ☆ button on any block to save your first template.</div>'));modalBody.querySelectorAll('[data-edit-template]').forEach(btn=>btn.onclick=()=>{close();openCourse(btn.dataset.editTemplate).catch(error);});modalBody.querySelectorAll('[data-remove-template]').forEach(btn=>btn.onclick=()=>confirmAction('Archive this template?','Existing courses will keep their copies of this block.',async()=>{const result=await read('get',btn.dataset.removeTemplate);await request('archive',{id:btn.dataset.removeTemplate,version:result.version});templates=await read('templates');manageTemplates();}));}

async function saveTemplate(){const b=selectedBlock();if(!b)return;const name=prompt('Template name',b.title||meta(b.type).label);if(!name)return;const data=newCourse(name);data.lessons[0].blocks=[clone(b)];await request('create',{id:data.id,data,kind:'template'});templates=await read('templates');notify('Block template saved. Find it in Add block → Templates.');}
function moveBlockDialog(id){show('<h2>Move block to a lesson</h2><div class="block-library">'+course.lessons.filter(l=>l.id!==lessonId).map(l=>'<button data-move-target="'+l.id+'">'+esc(l.title)+'</button>').join('')+'</div>');modalBody.querySelectorAll('[data-move-target]').forEach(btn=>btn.onclick=()=>{remember(true);const l=selectedLesson(),n=l.blocks.findIndex(b=>b.id===id);course.lessons.find(x=>x.id===btn.dataset.moveTarget).blocks.push(l.blocks.splice(n,1)[0]);blockId=null;close();changed(true);});}
function preview(){show('<div class="preview-controls"><h2>Learner preview</h2><button class="small" data-device="desktop">Desktop</button><button class="small" data-device="tablet">Tablet</button><button class="small" data-device="phone">Phone</button><button class="small" id="restart-preview">Restart</button></div><div class="preview-frame" id="preview-frame"></div>','preview-dialog');const start=()=>{previewInstance?.destroy();previewInstance=mountCourse(byId('preview-frame'),clone(course),{preview:true});};start();modalBody.querySelectorAll('[data-device]').forEach(btn=>btn.onclick=()=>{byId('preview-frame').className='preview-frame '+(btn.dataset.device==='desktop'?'':btn.dataset.device);});byId('restart-preview').onclick=start;}
async function publishDialog(){const errors=validatePublish(course);if(errors.length){show('<h2>A few fields need attention</h2><p>Complete these items before publishing.</p><ul class="error-list">'+errors.map(e=>'<li>'+esc(e)+'</li>').join('')+'</ul>');return;}
 await flush();const link=location.origin+'/lesson-player.html?course='+course.id;show('<h2>Publish your course</h2><p>The learner link will show a snapshot of your current draft. Future edits remain in the studio until you publish again.</p><div class="notice">'+course.lessons.length+' lessons · '+course.lessons.reduce((n,l)=>n+l.blocks.length,0)+' blocks. Learners enter through the existing website PIN.</div><div class="hero-actions"><button id="publish-now" class="primary">Publish current draft</button><button id="unpublish">Unpublish learner version</button></div><div id="publish-result"></div>');
 byId('publish-now').onclick=async()=>{byId('publish-now').disabled=true;try{const result=await request('publish',{id:course.id,version});version=result.version;backup();byId('publish-result').innerHTML='<div class="notice"><strong>Your course is published.</strong><p><a href="'+esc(link)+'" target="_blank" rel="noopener">Open learner course ↗</a></p><button id="copy-course-link">Copy learner link</button></div>';byId('copy-course-link').onclick=()=>copy(link);setStatus('Published · draft saved ✓');}catch(e){error(e);}finally{byId('publish-now').disabled=false;}};
 byId('unpublish').onclick=async()=>{try{const result=await request('unpublish',{id:course.id,version});version=result.version;backup();close();notify('Learner version unpublished. Your draft remains editable.');}catch(e){error(e);}};
}
async function historyDialog(){await flush();const entries=await read('history',course.id);show('<h2>Course version history</h2><p>Recent saved drafts are retained. Restoring a version changes the draft; publish again when it is ready.</p>'+entries.map((entry,n)=>'<div class="history-row"><span>Version '+entry.version+' · '+new Date(entry.created_at).toLocaleString()+'</span><button data-restore="'+n+'">Restore draft</button></div>').join('')+(entries.length?'':'<div class="notice">History appears after your first saved change.</div>'));modalBody.querySelectorAll('[data-restore]').forEach(btn=>btn.onclick=()=>{remember(true);course=normalizeCourse(entries[Number(btn.dataset.restore)].data);lessonId=course.lessons[0].id;blockId=null;close();changed(true);notify('Earlier draft restored. Publish again to update the learner course.');});}
function exportDialog(){show('<h2>Export your course</h2><p>Keep an editable backup, share a scrolling web course, or upload a package to an LMS.</p><div class="block-library"><button class="block-option" data-export="json"><span>⧉</span><div><strong>Editable JSON backup</strong><small>Content and uploaded assets. Import back into this studio.</small></div></button><button class="block-option" data-export="html"><span>↗</span><div><strong>Standalone HTML</strong><small>One scrolling course with your uploaded media.</small></div></button><button class="block-option" data-export="web"><span>▣</span><div><strong>Web ZIP</strong><small>A course ready to host on another website.</small></div></button><button class="block-option" data-export="scorm12"><span>✓</span><div><strong>SCORM 1.2</strong><small>Completion, scores, and LMS resume data.</small></div></button><button class="block-option" data-export="scorm2004"><span>✓</span><div><strong>SCORM 2004</strong><small>Completion, success, scores, and resume data.</small></div></button></div><div id="export-status" class="local-note"></div>');modalBody.querySelectorAll('[data-export]').forEach(btn=>btn.onclick=()=>exportCourse(btn.dataset.export).catch(error));}
async function exportCourse(type){setStatus('Preparing export…');if(byId('export-status'))byId('export-status').textContent='Preparing the course and its uploaded files…';const module=await import('./lesson-export.js');const artifact=await module.exportArtifact(clone(course),type);download(artifact.blob,artifact.name,artifact.mime);setStatus(dirty?'Draft has unsaved changes':'Saved to website ✓',dirty);if(byId('export-status'))byId('export-status').textContent='Export ready. Your browser will download it.';}
function download(data,name,mime){const blob=data instanceof Blob?data:new Blob([data],{type:mime}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
async function copy(text){try{await navigator.clipboard.writeText(text);notify('Learner link copied.');}catch{show('<h2>Copy learner link</h2><input id="copy-fallback" value="'+esc(text)+'">');byId('copy-fallback').select();}}
async function upload(file){if(file.size>20*1000*1000)throw Error('Choose a file no larger than 20 MB. Link to larger videos instead.');setStatus('Uploading '+file.name+'…');let source=file;
 if(['image/png','image/jpeg','image/webp'].includes(file.type)){const bitmap=await createImageBitmap(file);const scale=Math.min(1,1600/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);source=await new Promise(resolve=>canvas.toBlob(resolve,file.type==='image/png'?'image/png':'image/jpeg',.88));bitmap.close();}
 const bytes=new Uint8Array(await source.arrayBuffer());const partSize=512*1024-2,parts=Math.max(1,Math.ceil(bytes.length/partSize));const id=uid();const supported=['image/jpeg','image/png','image/webp','image/gif','video/mp4','video/webm','audio/mpeg','audio/wav','audio/ogg','audio/webm','application/pdf','text/plain'];const mime=supported.includes(source.type)?source.type:'application/octet-stream';
 await request('asset-init',{id,name:file.name,mime,parts});for(let part=0;part<parts;part++){const slice=bytes.subarray(part*partSize,(part+1)*partSize);let binary='';for(let n=0;n<slice.length;n+=8192)binary+=String.fromCharCode(...slice.subarray(n,n+8192));await request('asset-part',{id,part,data:btoa(binary)});setStatus('Uploading… '+Math.round((part+1)/parts*100)+'%');}
 setStatus('File uploaded ✓');return '/api/lesson-studio?action=asset&id='+id;
}
function pickUpload(path,kind){const obj=editingObject(),input=document.createElement('input');input.type='file';input.accept=kind==='image'?'image/png,image/jpeg,image/webp,image/gif':kind==='video'?'video/mp4,video/webm':kind==='audio'?'audio/mpeg,audio/wav,audio/ogg,audio/webm':'.pdf,.docx,.pptx,.xlsx,.txt,.zip';input.onchange=async()=>{const file=input.files[0];if(!file)return;try{const url=await upload(file);if(editingObject()!==obj){notify('File uploaded. Re-select the original block to attach it.');return;}remember(true);put(obj,path,url);if(kind==='attachment')obj.fileName=file.name;changed();renderPanel();}catch(e){setStatus('Upload failed',true);error(e);}};input.click();}
function stockPicker(path){const obj=editingObject();const names=['ct-hero.jpg','ct-define.jpg','ct-understand.jpg','ct-question.jpg','ct-analyze.jpg','ct-definition.jpg','ct-barriers-banner.jpg','ct-process-banner.jpg','ct-outward-inward.jpg','ct-brain-efficiency.jpg'];show('<h2>Images from your site</h2><p>Choose an existing image or upload your own through the content panel.</p><div class="block-library">'+names.map(name=>'<button data-stock-image="'+name+'"><img class="media-preview" src="/assets/'+name+'" alt="'+esc(name.replace(/ct-|\.jpg/g,'').replace(/-/g,' '))+'">'+esc(name.replace(/ct-|\.jpg/g,'').replace(/-/g,' '))+'</button>').join('')+'</div>');modalBody.querySelectorAll('[data-stock-image]').forEach(btn=>btn.onclick=()=>{remember(true);put(obj,path,'/assets/'+btn.dataset.stockImage);close();changed();renderPanel();});}
function toolPicker(){const obj=editingObject(),tools=[['Thinking tools','tools.html'],['Decision matrix','decision-matrix.html'],['Facilitator Timer Studio','classroom-timers.html'],['Critical thinking course','critical-thinking-foundations.html'],['Classroom Response Studio','word-cloud-studio.html'],['Selection Studio','selection-studio.html'],['Discussion Studio','discussion-studio.html']];show('<h2>Embed a site tool</h2><p>The tool appears in the scrolling lesson. Its own editing controls continue to work when opened separately.</p><div class="block-library">'+tools.map((t,n)=>'<button data-tool="'+n+'">'+esc(t[0])+'</button>').join('')+'</div>');modalBody.querySelectorAll('[data-tool]').forEach(btn=>btn.onclick=()=>{remember(true);const t=tools[Number(btn.dataset.tool)];obj.url=location.origin+'/'+t[1];obj.title=t[0];close();changed();renderPanel();});}
async function recordAudio(){const btn=byId('record-audio'),info=byId('record-status'),recordedBlock=selectedBlock();if(recording){recording.stop();return;}try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});const recorder=new MediaRecorder(stream);const parts=[];recording=recorder;btn.textContent='Stop recording ■';info.textContent='Recording… microphone is active.';recorder.ondataavailable=e=>parts.push(e.data);recorder.onstop=async()=>{stream.getTracks().forEach(t=>t.stop());recording=null;btn.textContent='Record narration 🎙';try{const file=new File(parts,'Narration.webm',{type:'audio/webm'});const url=await upload(file);if(!course||!course.lessons.some(l=>l.blocks.includes(recordedBlock))){notify('Narration uploaded, but the original course is no longer open.');return;}remember(true);recordedBlock.url=url;changed();renderPanel();}catch(e){error(e);}};recorder.start();}catch(e){notify('Microphone recording is unavailable. You can upload an audio file.');}}
function pasteDialog(){show('<h2>Turn your content into blocks</h2><p>Paste plain text. Blank lines create paragraph blocks. Lines starting with # become headings.</p><textarea id="bulk-paste" rows="12" placeholder="# Lesson heading&#10;&#10;Your first paragraph…"></textarea><button id="paste-create" class="primary" style="margin-top:15px">Add content blocks</button>');byId('paste-create').onclick=()=>{const parts=byId('bulk-paste').value.split(/\n\s*\n/).map(s=>s.trim()).filter(Boolean);if(!parts.length)return;remember(true);for(const part of parts){const heading=part.startsWith('#'),b=newBlock(heading?'heading':'text');if(heading)b.title=part.replace(/^#+\s*/,'');else{b.title='';b.body='<p>'+esc(part).replace(/\n/g,'<br>')+'</p>';}selectedLesson().blocks.push(b);}close();changed(true);notify(parts.length+' content blocks added.');};}
function importSiteDialog(){const choices=[['Critical Thinking Foundations','critical-thinking-foundations.html'],['Creative Thinking','creative-thinking-foundations.html'],['Systems Thinking','systems-thinking-foundations.html'],['Strategic Thinking','strategic-thinking-foundations.html'],['Strategic Leadership','strategic-leadership.html'],['Metacognition','metacognition.html'],['Leading Like Lasso','leading-like-lasso.html']];show('<h2>Import an existing site lesson</h2><p>Copy its static headings, paragraphs, lists, and images into a new editable lesson. Custom interactions and scripts remain in the original tool and can be added with an Embed block.</p><select id="site-lesson">'+choices.map((x,n)=>'<option value="'+n+'">'+esc(x[0])+'</option>').join('')+'</select><button class="primary" id="import-site-now" style="margin-top:16px">Import lesson content</button>');byId('import-site-now').onclick=async()=>{const choice=choices[Number(byId('site-lesson').value)];try{const r=await fetch('/'+choice[1]);if(!r.ok)throw Error('Lesson unavailable.');const doc=new DOMParser().parseFromString(await r.text(),'text/html');const main=doc.querySelector('main')||doc.body;const blocks=[];for(const el of main.querySelectorAll('h1,h2,h3,p,ul,ol,img')){if(el.closest('nav,footer,header,script,style,button')||el.parentElement.closest('ul,ol'))continue;const text=el.textContent.trim();if(el.tagName==='IMG'){const b=newBlock('image');b.title='';b.image=new URL(el.getAttribute('src'),location.origin+'/'+choice[1]).href;b.alt=el.alt;blocks.push(b);}else if(/^H[1-3]$/.test(el.tagName)&&text){const b=newBlock('heading');b.title=text;blocks.push(b);}else if(text){const b=newBlock('text');b.title='';b.body=safeHTML(el.outerHTML);blocks.push(b);}if(blocks.length>=300)break;}if(!blocks.length)throw Error('This lesson builds its content with scripts. Use an Embed block or paste its text into editable blocks.');remember(true);const l=newLesson(choice[0]+' (editable copy)');l.blocks=blocks;course.lessons.push(l);lessonId=l.id;blockId=null;panel='lesson';close();changed(true);notify(blocks.length+' content blocks imported. Review the copy before publishing.');}catch(e){error(e);}};}
byId('import-file').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>150*1024*1024)throw Error('Backup exceeds the 150 MB import limit.');const data=JSON.parse(await file.text());const normalized=normalizeCourse({...data,assets:undefined});if(data.assets){setStatus('Restoring uploaded media…');const replacements=new Map();for(const [url,asset] of Object.entries(data.assets)){const response=await fetch(asset);const blob=await response.blob();const newURL=await upload(new File([blob],'Imported_resource',{type:blob.type}));replacements.set(url,newURL);}const replace=o=>{for(const key of Object.keys(o)){const v=o[key];if(typeof v==='string'&&replacements.has(v))o[key]=replacements.get(v);else if(v&&typeof v==='object')replace(v);}};replace(normalized);}refreshIds(normalized);await createCourse(normalized);}catch(e){error(e);}};
byId('help-button').onclick=()=>show('<h2>Build a lesson in five steps</h2><ol class="lesson-list"><li><strong>Create a course.</strong> Use a blank course or the editable leadership sample.</li><li><strong>Add lessons and blocks.</strong> Choose the content or practice format, then fill in its forms.</li><li><strong>Arrange and style.</strong> Drag block handles, use the arrows, and adjust colors, padding, and layout in Design.</li><li><strong>Preview and refine.</strong> Test every interaction. Use required blocks and Continue gates to guide the experience.</li><li><strong>Publish or export.</strong> Share the learner link, download an editable backup, or export HTML / SCORM.</li></ol><div class="notice">Course drafts and uploaded files save to the website. Everyone with the site PIN can author shared courses. Device backups help recover interrupted saves. Learner progress, reflections, and ratings are saved in the learner’s browser.</div><p>This studio provides a Rise-style authoring workflow. It does not include Articulate’s proprietary AI, stock content, Review 360, translation service, or its native project import format. SCORM packages need a test in your LMS before formal use. Custom code and third-party embeds can affect accessibility.</p>');
window.addEventListener('beforeunload',e=>{if(dirty){backup();e.preventDefault();e.returnValue='';}if(recording)recording.stream?.getTracks().forEach(t=>t.stop());});
window.addEventListener('keydown',e=>{if(!course||e.target.closest('input,textarea,[contenteditable]'))return;if((e.ctrlKey||e.metaKey)&&e.key==='z'){e.preventDefault();undo(e.shiftKey);}if((e.ctrlKey||e.metaKey)&&e.key==='s'){e.preventDefault();flush().catch(error);}});
window.addEventListener('online',()=>{if(course&&dirty)flush().catch(error);});
await library();

const requestedCourse=new URLSearchParams(location.search).get('course');
if(requestedCourse && /^[a-f0-9-]{36}$/i.test(requestedCourse))await openCourse(requestedCourse).catch(error);
